mapper.select:
select f.FileTitle as ccFileTitle, fa.ActName as ccActName, u.U_Name as ccCreateName, u1.U_Name as ccUserName, flow.FlowName as ccFlowName, pro.P_Name as pName, sec.Sec_Name as secName, con.Con_Name as conName, f.T_Code as tCode, f.FileFlowStatus as fileflowstatus, f.FileCreateUser as filecreateuser, f.FileCreateUserName as filecreateusername,
from SYS_CarbonCopy cc left join SYS_FlowActivity fa on fa.ActID=cc.CC_ActID left join SYS_Flow flow on flow.FlowID=cc.CC_FlowID left join Sys_File f on f.FileID=cc.CC_FileID left join Sys_User u on u.U_Id=cc.CC_CreateUser left join Sys_User u1 on u1.U_Id=cc.CC_User left join Pre_Project pro on pro.P_ID=f.FileProject left join Sec_Info sec on sec.Sec_Id=f.FileSectionID left join Con_Contract con on con.Con_Id=f.FileContract
cc.CC_User=#{params.userId}
and cc.CC_Read = #{params.ccRead}
and cc.CC_Time between #{params.ccSendStartTime} and #{params.ccSendEndTime}
and cc.CC_ReadTime between #{params.ccReadStartTime} and #{params.ccReadEndTime}
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
and u.U_Name like concat('%',#{params.ccCreateName},'%')
and cc.CC_Title like concat('%',#{params.ccTitle},'%')
and cc.CC_Title in
#{ccTitle}
and pro.P_Name in
#{ccTitle}
and f.FileCreateUserName in
#{ccTitle}
and cc.Te_Id = #{params.teId}
order by cc.${params.sortFiled} ${params.sortType}
limit #{params.start},#{params.size}

select
  COUNT(1)
from  SYS_CarbonCopy cc
left join  Sys_File f on f.FileID=cc.CC_FileID
left join  Sys_User u on u.U_Id=cc.CC_CreateUser
left join  Pre_Project pro on pro.P_ID=f.FileProject
left join  Con_Contract con on con.Con_Id=f.FileContract

    cc.CC_User=#{params.userId}
    
        and cc.CC_Read = #{params.ccRead}
    
    
        and cc.CC_Time between #{params.ccSendStartTime} and #{params.ccSendEndTime}
    
    
        and cc.CC_ReadTime between #{params.ccReadStartTime} and #{params.ccReadEndTime}
    
    
        
            
                and likePname(#{params.pName},pro.P_Id)=true
            
        
        
            
                and pro.P_Name like concat('%',#{params.pName},'%')
            
        
    
    
        and con.Con_Name like concat('%',#{params.conName},'%')
    
    
        and u.U_Name like concat('%',#{params.ccCreateName},'%')
    
    
        and cc.CC_Title like concat('%',#{params.ccTitle},'%')
    
    
        and cc.CC_Title in
        
            #{ccTitle}
        
    
    
        and pro.P_Name in
        
            #{ccTitle}
        
    
    
        and f.FileCreateUserName in
        
            #{ccTitle}
        
    
    
        and cc.Te_Id = #{params.teId}

        select
        DISTINCT  ${key}
        from SYS_CarbonCopy cc
        left join SYS_FlowActivity fa on fa.ActID=cc.CC_ActID
        left join SYS_Flow flow on flow.FlowID=cc.CC_FlowID
        left join Sys_File f on f.FileID=cc.CC_FileID
        left join Sys_User u on u.U_Id=cc.CC_CreateUser
        left join Sys_User u1 on u1.U_Id=cc.CC_User
        left join Pre_Project pro on pro.P_ID=f.FileProject
        left join Sec_Info sec on sec.Sec_Id=f.FileSectionID
        left join Con_Contract con on con.Con_Id=f.FileContract
        
            cc.CC_User=#{params.userId}
            
                and cc.CC_Read = #{params.ccRead}
            
            
                and cc.CC_Time between #{params.ccSendStartTime} and #{params.ccSendEndTime}
            
            
                and cc.CC_ReadTime between #{params.ccReadStartTime} and #{params.ccReadEndTime}
            
            
                
                    
                        and likePname(#{params.pName},pro.P_Id)=true
                    
                
                
                    
                        and pro.P_Name like concat('%',#{params.pName},'%')
                    
                
            
            
                and con.Con_Name like concat('%',#{params.conName},'%')
            
            
                and u.U_Name like concat('%',#{params.ccCreateName},'%')
            
            
                and cc.CC_Title like concat('%',#{params.ccTitle},'%')
            
            
                and cc.CC_Title in
                
                    #{ccTitle}
                
            
            
                and pro.P_Name in
                
                    #{ccTitle}
                
            
            
                and f.FileCreateUserName in
                
                    #{ccTitle}
                
            

            
                and cc.Te_Id = #{params.teId}

select f.FileTitle as ccFileTitle, fa.ActName as ccActName, u.U_Name as ccCreateName, flow.FlowName as ccFlowName, pro.P_Name as pName, sec.Sec_Name as secName, con.Con_Name as conName, u1.U_Name as ccUserName, f.T_Code as tCode,
from SYS_CarbonCopy cc left join SYS_FlowActivity fa on fa.ActID=cc.CC_ActID left join SYS_Flow flow on flow.FlowID=cc.CC_FlowID left join Sys_File f on f.FileID=cc.CC_FileID left join Sys_User u on u.U_Id=cc.CC_CreateUser left join Pre_Project pro on pro.P_ID=f.FileProject left join Sec_Info sec on sec.Sec_Id=f.FileSectionID left join Con_Contract con on con.Con_Id=f.FileContract left join Sys_User u1 on u1.U_Id=cc.CC_User
and cc.CC_Read = #{params.ccRead}
and cc.CC_Time between #{params.ccSendStartTime} and #{params.ccSendEndTime}
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
and u.U_Name like concat('%',#{params.ccCreateName},'%')
and u1.U_Name like concat('%',#{params.ccUserName},'%')
and cc.CC_Title like concat('%',#{params.ccTitle},'%')
and cc.Te_Id = #{params.teId}
order by cc.${params.sortFiled} ${params.sortType}
limit #{params.start},#{params.size}

select COUNT(1) from SYS_CarbonCopy cc left join Sys_File f on f.FileID=cc.CC_FileID left join Sys_User u on u.U_Id=cc.CC_CreateUser left join Pre_Project pro on pro.P_ID=f.FileProject left join Con_Contract con on con.Con_Id=f.FileContract left join Sys_User u1 on u1.U_Id=cc.CC_User
and cc.CC_Read = #{params.ccRead}
and cc.CC_Time between #{params.ccSendStartTime} and #{params.ccSendEndTime}
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
and u.U_Name like concat('%',#{params.ccCreateName},'%')
and u1.U_Name like concat('%',#{params.ccUserName},'%')
and cc.CC_Title like concat('%',#{params.ccTitle},'%')
and cc.Te_Id = #{params.teId}

select f.T_Code as tCode,
count(*)  as total
from SYS_CarbonCopy tk
left join Sys_File f on f.FileId=tk.CC_FileID

    Cc_Read='未阅'
    
        and tk.CC_User=#{params.uId}
    
     and  f.T_Code in
    
        #{code}
    
    
        and f.Te_Id = #{teId}
    

group by f.T_Code

SELECT DISTINCT u.U_ID FROM SYS_User u LEFT JOIN SYS_Position_User_P pu ON u.U_ID = pu.U_ID LEFT JOIN SYS_Position_P p ON pu.PP_ID = p.PP_ID LEFT JOIN SYS_Department_P d ON d.PD_ID = p.PD_ID LEFT JOIN SYS_Company c ON c.C_ID = u.C_ID LEFT JOIN Pre_Project pro ON pro.P_Id = d.P_Id WHERE pro.P_Id = #{pId} AND d.PD_Type = '0' AND u.C_ID IN
#{unitId}
AND d.PD_Code IN
#{depCode}
AND p.PP_Code IN
#{posCode}
